//! The cyclotomic quotient `T^λ` of a weighted KLR algebra with red strands (context key
//! `quotient=cyclotomic`; conventions: `docs/klrw.md`, "Red strands and tensor product
//! algebras").
//!
//! `T^λ` is `T̃^λ` modulo the two-sided ideal `I` generated by the idempotents `e_V` of the
//! violating loadings `V`, those whose leftmost strand is black (B. Webster, *Knot invariants and
//! higher representation theory*, arXiv:1309.3796v2, §4). Equality in `T^λ` is decided degree by
//! degree: in the free `k[x]`-module `e_{B'} T̃ e_B` with basis `b_π`, the degree-`d` part of
//! `e_{B'} I e_B` is spanned by
//!
//! * the sandwiches `b_σ x^c b_τ` of degree `d`, through a representative `V` of every order
//!   type of violating loadings with the colours of `B`, and
//! * `v x_k` for `v` in the degree `d − 2 d_{i_k}` part (a dot at the bottom of a basis
//!   element `b_π x^m` is again a basis element).
//!
//! Both spans are finite: `e_{B'} T̃ e_B` is finite-dimensional in each degree. Reducing a
//! homogeneous component modulo that span gives a unique representative, which is the normal form
//! in `T^λ`. This needs the coefficients to form a field (no free scalars).
//!
//! The violating order types are enumerated exactly: an order type is a choice of side for every
//! comparison of a point with a ghost it interacts with, with a red strand, and of two ghosts of
//! different weights, and the choices that occur are those whose strict difference constraints
//! `x_a − x_b < c` are feasible (no cycle of nonpositive total weight, found by Bellman–Ford over
//! `c − ε`). A feasible system gives an explicit rational loading.

use super::klrw::{Klrw, Summand};
use super::weighted::{Loading, Op, OrderType, Q};
use crate::error::{Error, Result};
use crate::linalg::Reducer;
use crate::perm::Perm;
use crate::poly::{Monomial, Poly, PolyRing};
use crate::ring::Ring;
use num_traits::{One, Zero};
use std::collections::BTreeMap;
use std::sync::{Arc, Mutex};

type C<R> = Poly<<R as Ring>::Elem>;
type Col = (Perm, Vec<u32>);
/// A homogeneous component: bottom loading, top loading, and degree.
type Key = (Loading, Loading, i64);

/// The degree-`d` part of `e_{B'} I e_B`: its column basis `b_π x^m` and a reducer for its span.
pub struct IdealPiece<R: Ring> {
    pub cols: Vec<Col>,
    pub index: BTreeMap<Col, usize>,
    pub span: Reducer<PolyRing<R>>,
}

/// Caches for the cyclotomic quotient.
pub struct Cyclotomic<R: Ring> {
    violating: Mutex<BTreeMap<Vec<u16>, Arc<Vec<Loading>>>>,
    pieces: Mutex<BTreeMap<Key, Arc<IdealPiece<R>>>>,
}

impl<R: Ring> Default for Cyclotomic<R> {
    fn default() -> Self {
        Cyclotomic {
            violating: Mutex::new(BTreeMap::new()),
            pieces: Mutex::new(BTreeMap::new()),
        }
    }
}

/// `x_a − x_b < c`, nodes `1..=n` the points and node `0` the origin.
type Cons = (usize, usize, Q);

fn lt(a: &(Q, i64), b: &(Q, i64)) -> bool {
    a.0 < b.0 || (a.0 == b.0 && a.1 < b.1)
}

/// Bellman–Ford over `c − ε`: potentials `A + B ε` satisfying every constraint, or `None`.
fn solve(nodes: usize, cons: &[Cons]) -> Option<Vec<(Q, i64)>> {
    let mut d = vec![(Q::zero(), 0i64); nodes];
    for it in 0..=nodes {
        let mut changed = false;
        for (a, b, c) in cons {
            let cand = (&d[*b].0 + c, d[*b].1 - 1);
            if lt(&cand, &d[*a]) {
                d[*a] = cand;
                changed = true;
            }
        }
        if !changed {
            return Some(d);
        }
        if it == nodes {
            return None;
        }
    }
    None
}

/// A rational point satisfying the constraints, from feasible potentials.
fn realize(d: &[(Q, i64)], cons: &[Cons]) -> Vec<Q> {
    let mut eps = Q::one();
    for (a, b, c) in cons {
        let da = &d[*a].0 - &d[*b].0;
        let db = d[*a].1 - d[*b].1;
        if da < *c && db > 0 {
            let bound = (c - &da) / Q::from_integer(db.into());
            if bound < eps {
                eps = bound;
            }
        }
    }
    eps /= Q::from_integer(2.into());
    let val = |k: usize| &d[k].0 + &eps * Q::from_integer(d[k].1.into());
    let origin = val(0);
    (1..d.len()).map(|k| val(k) - &origin).collect()
}

/// The distinct orderings of a multiset of colours.
fn arrangements(sorted: &[u16]) -> Vec<Vec<u16>> {
    fn go(left: &mut BTreeMap<u16, usize>, cur: &mut Vec<u16>, n: usize, out: &mut Vec<Vec<u16>>) {
        if cur.len() == n {
            out.push(cur.clone());
            return;
        }
        let keys: Vec<u16> = left.keys().copied().collect();
        for c in keys {
            if left[&c] == 0 {
                continue;
            }
            *left.get_mut(&c).unwrap() -= 1;
            cur.push(c);
            go(left, cur, n, out);
            cur.pop();
            *left.get_mut(&c).unwrap() += 1;
        }
    }
    let mut left = BTreeMap::new();
    for &c in sorted {
        *left.entry(c).or_insert(0) += 1;
    }
    let mut out = Vec::new();
    go(&mut left, &mut Vec::new(), sorted.len(), &mut out);
    out
}

/// The exponent vectors `m` with `Σ w_k m_k = total`.
fn monomials(weights: &[i64], total: i64) -> Vec<Vec<u32>> {
    fn go(w: &[i64], k: usize, rest: i64, cur: &mut Vec<u32>, out: &mut Vec<Vec<u32>>) {
        if k == w.len() {
            if rest == 0 {
                out.push(cur.clone());
            }
            return;
        }
        let mut e = 0;
        while e * w[k] <= rest {
            cur.push(e as u32);
            go(w, k + 1, rest - e * w[k], cur, out);
            cur.pop();
            e += 1;
        }
    }
    let mut out = Vec::new();
    if total >= 0 {
        go(weights, 0, total, &mut Vec::new(), &mut out);
    }
    out
}

/// Column order: longer permutations first, then larger exponents (as in the normal form).
fn col_order(a: &Col, b: &Col) -> std::cmp::Ordering {
    b.0.length()
        .cmp(&a.0.length())
        .then(a.0.cmp(&b.0))
        .then(b.1.cmp(&a.1))
}

impl<R: Ring> Klrw<R> {
    /// The permutations `π` with `colour(top_{π(k)}) = colour(bottom_k)`.
    fn compatible(&self, bottom: &Loading, top: &Loading) -> Vec<Perm> {
        let (cb, ct) = (bottom.colours(), top.colours());
        Perm::all(bottom.n())
            .into_iter()
            .filter(|p| (0..cb.len()).all(|k| ct[p.0[k] as usize] == cb[k]))
            .collect()
    }

    fn perm_degree(&self, bottom: &Loading, top: &Loading, p: &Perm) -> Result<i64> {
        let seg = self.data.segment(bottom, top, p)?;
        let colours = bottom.colours();
        Ok(seg
            .events
            .iter()
            .map(|e| self.data.event_degree(&colours, e))
            .sum())
    }

    fn dot_weights(&self, l: &Loading) -> Vec<i64> {
        l.colours()
            .iter()
            .map(|&c| 2 * self.data.d[c as usize])
            .collect()
    }

    /// One representative of every order type of violating loadings with these colours.
    pub fn violating(&self, colours: &[u16]) -> Arc<Vec<Loading>> {
        let cy = self.cyclo.as_ref().expect("a cyclotomic context");
        let mut key = colours.to_vec();
        key.sort();
        if let Some(v) = cy.violating.lock().unwrap().get(&key) {
            return v.clone();
        }
        let mut found: BTreeMap<OrderType, Loading> = BTreeMap::new();
        if !key.is_empty() {
            for seq in arrangements(&key) {
                self.violating_with(&seq, &mut found);
            }
        }
        let out = Arc::new(found.into_values().collect::<Vec<_>>());
        cy.violating.lock().unwrap().insert(key, out.clone());
        out
    }

    fn violating_with(&self, seq: &[u16], found: &mut BTreeMap<OrderType, Loading>) {
        let n = seq.len();
        let mut base: Vec<Cons> = Vec::new();
        for k in 1..n {
            base.push((k, k + 1, Q::zero()));
        }
        if let Some(r) = self.data.reds.first() {
            base.push((1, 0, r.pos.clone()));
        }
        // Each choice: two alternative constraints.
        let mut bits: Vec<[Cons; 2]> = Vec::new();
        for e in &self.data.edges {
            for j in 0..n {
                if seq[j] != e.tail {
                    continue;
                }
                for (k, &ck) in seq.iter().enumerate() {
                    if ck == e.head && k != j {
                        let t = e.weight.clone();
                        bits.push([(j + 1, k + 1, t.clone()), (k + 1, j + 1, -t)]);
                    }
                }
            }
        }
        for j in 0..n {
            for r in &self.data.reds {
                let p = r.pos.clone();
                bits.push([(j + 1, 0, p.clone()), (0, j + 1, -p)]);
            }
        }
        let ghosts: Vec<(usize, &Q)> = self
            .data
            .edges
            .iter()
            .flat_map(|e| {
                (0..n)
                    .filter(move |&k| seq[k] == e.head)
                    .map(move |k| (k, &e.weight))
            })
            .collect();
        for (i, (k, te)) in ghosts.iter().enumerate() {
            for (m, tf) in &ghosts[i + 1..] {
                if te != tf && k != m {
                    // ghosts at x_k + θ_e and x_m + θ_f: x_k − x_m against θ_f − θ_e
                    let c = *tf - *te;
                    bits.push([(k + 1, m + 1, c.clone()), (m + 1, k + 1, -c)]);
                }
            }
        }
        if solve(n + 1, &base).is_none() {
            return;
        }
        let mut cons = base;
        self.dfs(seq, &bits, 0, &mut cons, found);
    }

    fn dfs(
        &self,
        seq: &[u16],
        bits: &[[Cons; 2]],
        i: usize,
        cons: &mut Vec<Cons>,
        found: &mut BTreeMap<OrderType, Loading>,
    ) {
        if i == bits.len() {
            let Some(d) = solve(seq.len() + 1, cons) else {
                return;
            };
            let xs = realize(&d, cons);
            let l = Loading(seq.iter().copied().zip(xs).collect());
            if self.data.check_loading(&l).is_ok() {
                found.entry(self.data.order_type(&l)).or_insert(l);
            }
            return;
        }
        for alt in &bits[i] {
            cons.push(alt.clone());
            if solve(seq.len() + 1, cons).is_some() {
                self.dfs(seq, bits, i + 1, cons, found);
            }
            cons.pop();
        }
    }

    fn x_power(
        &self,
        rep: &super::weighted::PolyRep<'_, PolyRing<R>>,
        m: &[u32],
    ) -> C<PolyRing<R>> {
        let exps: Vec<i32> = m.iter().map(|&e| e as i32).collect();
        rep.alg
            .ring
            .monomial(Monomial(exps.into_iter().collect()), self.coeff_one())
    }

    fn coeff_one(&self) -> C<R> {
        self.klr.coeff.one()
    }

    /// The degree-`d` part of `e_{top} I e_{bottom}`.
    pub fn ideal_piece(
        &self,
        bottom: &Loading,
        top: &Loading,
        d: i64,
    ) -> Result<Arc<IdealPiece<R>>> {
        let cy = self.cyclo.as_ref().expect("a cyclotomic context");
        let key = (bottom.clone(), top.clone(), d);
        if let Some(p) = cy.pieces.lock().unwrap().get(&key) {
            return Ok(p.clone());
        }
        let wb = self.dot_weights(bottom);
        let mut cols: Vec<Col> = Vec::new();
        for p in self.compatible(bottom, top) {
            let dp = self.perm_degree(bottom, top, &p)?;
            for m in monomials(&wb, d - dp) {
                cols.push((p.clone(), m));
            }
        }
        cols.sort_by(col_order);
        let index: BTreeMap<Col, usize> = cols
            .iter()
            .cloned()
            .enumerate()
            .map(|(i, c)| (c, i))
            .collect();
        let ring = self.klr.coeff.clone();
        let mut span = Reducer::new(ring.clone(), cols.len());
        if !cols.is_empty() {
            // v x_k for v in lower degrees
            for (k, &w) in wb.iter().enumerate() {
                let lower = self.ideal_piece(bottom, top, d - w)?;
                for row in lower.span.sparse_basis() {
                    let mut v = vec![ring.zero(); cols.len()];
                    for (j, x) in row {
                        let (p, m) = &lower.cols[*j];
                        let mut m = m.clone();
                        m[k] += 1;
                        let idx = index.get(&(p.clone(), m)).ok_or_else(|| {
                            Error::invalid("internal: a shifted column is missing")
                        })?;
                        v[*idx] = x.clone();
                    }
                    span.insert(v);
                }
            }
            // sandwiches b_σ x^c b_τ through violating loadings
            let rep = self.rep(bottom.n());
            'outer: for v in self.violating(&bottom.colours()).iter() {
                let wv = self.dot_weights(v);
                let below: Vec<(Perm, i64)> = self
                    .compatible(bottom, v)
                    .into_iter()
                    .map(|t| Ok((t.clone(), self.perm_degree(bottom, v, &t)?)))
                    .collect::<Result<_>>()?;
                for s in self.compatible(v, top) {
                    let ds = self.perm_degree(v, top, &s)?;
                    let bs = rep.basis_op(v, top, &s)?;
                    for (t, dt) in &below {
                        let ms = monomials(&wv, d - ds - dt);
                        if ms.is_empty() {
                            continue;
                        }
                        let bt = rep.basis_op(bottom, v, t)?;
                        for c in ms {
                            if span.rank() == cols.len() {
                                break 'outer;
                            }
                            let top_op = rep.then_poly(&bs, &self.x_power(&rep, &c));
                            let op: Op<C<R>> = rep.compose(&top_op, &bt);
                            let nf = rep.normal_form(bottom, top, &op)?;
                            let mut vec = vec![ring.zero(); cols.len()];
                            for (p, f) in &nf {
                                for (mono, x) in &f.terms {
                                    let m: Vec<u32> = mono.0.iter().map(|&e| e as u32).collect();
                                    let idx = index.get(&(p.clone(), m)).ok_or_else(|| {
                                        Error::invalid("internal: an inhomogeneous sandwich")
                                    })?;
                                    vec[*idx] = ring.add(&vec[*idx], x);
                                }
                            }
                            span.insert(vec);
                        }
                    }
                }
            }
        }
        let piece = Arc::new(IdealPiece { cols, index, span });
        cy.pieces.lock().unwrap().insert(key, piece.clone());
        Ok(piece)
    }

    /// The graded dimension of `e_{top} T^λ e_{bottom}`: degree ↦ dimension, nonzero entries
    /// only. Degrees are computed upward from the least degree of a basis diagram until a run of
    /// `max_k 2 d_{i_k}` consecutive degrees above every basis diagram's degree is zero; from then
    /// on every column `b_π x^m` is a dot times a column of lower degree, so every higher degree
    /// is zero too.
    pub fn graded_dimension(
        &self,
        bottom: &Loading,
        top: &Loading,
    ) -> Result<BTreeMap<i64, usize>> {
        let perms = self.compatible(bottom, top);
        let mut out = BTreeMap::new();
        if perms.is_empty() {
            return Ok(out);
        }
        let degs: Vec<i64> = perms
            .iter()
            .map(|p| self.perm_degree(bottom, top, p))
            .collect::<Result<_>>()?;
        let (dmin, dmax) = (*degs.iter().min().unwrap(), *degs.iter().max().unwrap());
        let wmax = self
            .dot_weights(bottom)
            .into_iter()
            .max()
            .unwrap_or(1)
            .max(1);
        let mut run = 0;
        let mut d = dmin;
        loop {
            let piece = self.ideal_piece(bottom, top, d)?;
            let free = piece.cols.len() - piece.span.rank();
            if free > 0 {
                out.insert(d, free);
                run = 0;
            } else {
                run += 1;
            }
            if d >= dmax && run >= wmax {
                return Ok(out);
            }
            if d - dmin > 100_000 {
                return Err(Error::invalid(
                    "internal: the cyclotomic quotient does not vanish in high degree",
                ));
            }
            d += 1;
        }
    }

    /// Reduces normal-form summands modulo the violating ideal.
    pub fn reduce_cyclotomic(&self, nf: Vec<Summand<C<R>>>) -> Result<Vec<Summand<C<R>>>> {
        let ring = self.klr.coeff.clone();
        let mut groups: BTreeMap<Key, Vec<Summand<C<R>>>> = BTreeMap::new();
        for s in nf {
            let d = self.degree(&s)?;
            groups
                .entry((s.bottom.clone(), s.top.clone(), d))
                .or_default()
                .push(s);
        }
        let mut out = Vec::new();
        for ((bottom, top, d), ss) in groups {
            let piece = self.ideal_piece(&bottom, &top, d)?;
            let mut v = vec![ring.zero(); piece.cols.len()];
            for s in &ss {
                let idx = piece
                    .index
                    .get(&(s.perm.clone(), s.dots.clone()))
                    .ok_or_else(|| Error::invalid("internal: a summand outside its piece"))?;
                v[*idx] = ring.add(&v[*idx], &s.coeff);
            }
            for (j, x) in piece.span.reduce(&v).into_iter().enumerate() {
                if !ring.is_zero(&x) {
                    out.push(Summand {
                        bottom: bottom.clone(),
                        top: top.clone(),
                        perm: piece.cols[j].0.clone(),
                        dots: piece.cols[j].1.clone(),
                        coeff: x,
                    });
                }
            }
        }
        Ok(out)
    }
}

/// Checks that a context can use the cyclotomic quotient.
pub fn check_field<R: Ring>(base: &R, scalars: &[String]) -> Result<()> {
    if !base.is_field() || !scalars.is_empty() {
        return Err(Error::invalid(
            "quotient=cyclotomic needs a field of coefficients and no free scalars",
        ));
    }
    Ok(())
}
